UPDATE projects SET seoKeywords = 'scenic design, Blithe Spirit, Noël Coward, Okoboji Summer Theatre, supernatural comedy' WHERE slug = 'blithe-spirit';

INSERT IGNORE INTO tags (name) VALUES ('Noël Coward'), ('Supernatural'), ('British Comedy');

INSERT IGNORE INTO projectTags (projectId, tagId)
